% =========================================================================
% RUN THE SIMULATION
% input:    run_param
%           kgrid
%           medium
%           source
%           sensor
% output:   sensor_data
%
% Compute sensor data of waves generated by oscillating microbubbles in a
% homogeneous medium. Nonlinear propagation is neglected.
%
% Memory use is bounded by processing the sensors in chunks and, when the
% distances are not gridded, several sources at once. The number of
% elements of the intermediate arrays (about four complex arrays of the
% same size live at once) is bounded by run_param.MaxArrayElements
% (default 2^26) as long as a single sensor fits (2*Nt*4 elements). On the GPU, the output stays
% on the GPU if it has at most run_param.MaxGpuElements elements (default
% 2^30) and is otherwise accumulated on the CPU.
%
% =========================================================================
function sensor_data = run_simulation_homogeneous(...
    run_param, kgrid, medium, source, sensor)

% Compute the average properties of the medium (homogeneous medium
% approximation):
medium = average_medium(medium);

N_source    = size(source.points,1);   	% Number of sources
N_sensor    = size(sensor.points,1);   	% Number of sensors
Nt          = kgrid.Nt;

maxElements    = get_param(run_param, 'MaxArrayElements', 2^26);
maxGpuElements = get_param(run_param, 'MaxGpuElements',   2^30);

dataType = class(source.mass_source); % 'single' or 'double'
useGPU   = startsWith(run_param.DATA_CAST, 'gpuArray');

% Preallocate sensor data:
if useGPU
    disp(['Selected and reset GPU device ' ...
        num2str(run_param.DEVICE_NUM) '.']);
    gpuDevice(run_param.DEVICE_NUM + 1);
    source.mass_source = gpuArray(source.mass_source);
end
if useGPU && N_sensor*Nt <= maxGpuElements
    sensor_data.p = gpuArray(zeros(N_sensor, Nt, dataType));
else
    sensor_data.p = zeros(N_sensor, Nt, dataType);
end

% Sensor chunk size for adding gridded pressures to the output:
NchunkGridded = max(1, floor(maxElements/Nt));

if run_param.gridded
    % The distances to each source are snapped to a grid spanning all
    % sensors, so the sources are processed one by one (the gridded
    % pressure arrays are small).
    for m = 1:N_source
        disp(['Propagating source ' num2str(m) '/' num2str(N_source) ' ...'])

        d0 = vecnorm(sensor.points - source.points(m,:), 2, 2);
        [d, i_sampled] = gridded_distance(d0, kgrid.dt*medium.c);

        p = calc_scatter_attenuated(source.mass_source(m,:), medium, ...
            kgrid, to_device(d, dataType, useGPU));

        % Prevent sources from self-sensing:
        silent = (d0 == 0);

        % Add the gridded pressure to the sensors, chunk by chunk so that
        % no array of the full output size is created on the GPU:
        for i1 = 1:NchunkGridded:N_sensor
            idx = i1:min(i1+NchunkGridded-1, N_sensor);
            p_chunk = p(i_sampled(idx),:);
            p_chunk(silent(idx),:) = 0;
            sensor_data.p(idx,:) = sensor_data.p(idx,:) + ...
                cast_like(p_chunk, sensor_data.p);
        end
    end
    return
end

% Not gridded: process chunks of sensors and batches of sources. The
% largest intermediate arrays have Nchunk*2*Nt*Nbatch complex elements and
% about four of them exist at once in calc_scatter_attenuated.
Nchunk = max(1, min(N_sensor, floor(maxElements/(8*Nt))));
Nbatch = max(1, min(N_source, floor(maxElements/(8*Nt*Nchunk))));

for i1 = 1:Nchunk:N_sensor
    idx = i1:min(i1+Nchunk-1, N_sensor);
    p_chunk = zeros(numel(idx), Nt, dataType);
    if useGPU; p_chunk = gpuArray(p_chunk); end

    for m1 = 1:Nbatch:N_source
        m = m1:min(m1+Nbatch-1, N_source);
        disp(['Propagating sources ' num2str(m(1)) '-' num2str(m(end)) ...
            '/' num2str(N_source) ' to sensors ' num2str(idx(1)) '-' ...
            num2str(idx(end)) '/' num2str(N_sensor) ' ...'])

        % Distance between each sensor and each source (Nchunk-by-Nbatch);
        % zero distances give zero pressure (no self-sensing):
        d = vecnorm(sensor.points(idx,:) - ...
            permute(source.points(m,:),[3 2 1]), 2, 2);
        d = reshape(d, numel(idx), numel(m));

        p = calc_scatter_attenuated(source.mass_source(m,:), medium, ...
            kgrid, to_device(d, dataType, useGPU));
        p_chunk = p_chunk + sum(p, 3);
    end

    sensor_data.p(idx,:) = cast_like(p_chunk, sensor_data.p);
end

end

function value = get_param(run_param, name, default)
if isfield(run_param, name)
    value = run_param.(name);
else
    value = default;
end
end

function x = to_device(x, dataType, useGPU)
% Convert to the requested data type (and to the GPU if requested).
x = cast(x, dataType);
if useGPU
    x = gpuArray(x);
end
end

function x = cast_like(x, target)
% Move x to the CPU if the target array is on the CPU.
if ~isa(target,'gpuArray') && isa(x,'gpuArray')
    x = gather(x);
end
end

function medium_average = average_medium(medium)
% Compute the average value of medium properties.

medium_average.rho = mean(medium.density,     'all');
medium_average.c   = mean(medium.sound_speed, 'all');
medium_average.a   = mean(medium.alpha_coeff, 'all');
medium_average.b   = mean(medium.alpha_power, 'all');

if isfield(medium,'alpha_mode')
    medium_average.alpha_mode = medium.alpha_mode;
end

end

function [d_grid, i_grid] = gridded_distance(d, dx)
% Snap values in array d to a grid d_grid with step size dx.
% Grid is set up with respect to mean of d.
% The indices i_grid are defined such that d_grid(i_grid(n)) is the element
% closest to d(n).

% Set up grid:
i_grid = round((d - mean(d))/dx);
d_grid = (min(i_grid):max(i_grid))*dx + mean(d);
d_grid = transpose(d_grid);

% Return indices of grid corresponding to elements in d:
i_mean = -min(i_grid) + 1;
i_grid = i_grid + i_mean;

end
